<?php
require_once __DIR__.'/../config/config.php';
require_once __DIR__.'/auth.php';
if (!isLoggedIn()) { header('Location: ../login.php');exit; }
if (!isAdmin() && !isTeller()) { http_response_code(403);exit('Akses ditolak.'); }
$jenis=$_GET['jenis'] ?? '';$id=(int)($_GET['id'] ?? 0);
$tables=['denda'=>'layanan_bayar_denda','bayar'=>'layanan_pembayaran','bast'=>'layanan_jaminan_kembali','lelang'=>'layanan_lelang','bonus'=>'layanan_bonus'];
if($jenis==='bonus' && !isAdmin()){http_response_code(403);exit('Khusus Admin.');}
if (!isset($tables[$jenis]) || !layananSiap($db)) { http_response_code(404);exit('Dokumen tidak ditemukan.'); }
$table=$tables[$jenis];
$alias=$jenis==='lelang'?'b.harga_jual AS jumlah,':'';
$jaminanSelect=$jenis==='bast'?',j.jenis_barang,j.identitas_barang,j.deskripsi_barang,j.status_jaminan':'';
$jaminanJoin=$jenis==='bast'?' LEFT JOIN jaminan_pinjaman j ON j.pinjaman_id=p.id':'';
$angsuranSelect=$jenis==='denda'?',a.angsuran_ke,a.tanggal_jatuh_tempo':'';
$angsuranJoin=$jenis==='denda'?' LEFT JOIN angsuran a ON a.id=b.angsuran_id':'';
$stmt=$db->prepare("SELECT b.*,$alias p.kode_pinjaman,ag.nama_lengkap,ag.kode_anggota,ag.ktp,u.nama_lengkap petugas $jaminanSelect $angsuranSelect FROM $table b JOIN pinjaman p ON p.id=b.pinjaman_id JOIN anggota ag ON ag.id=p.anggota_id JOIN users u ON u.id=b.user_id $jaminanJoin $angsuranJoin WHERE b.id=?");$stmt->execute([$id]);$b=$stmt->fetch(PDO::FETCH_ASSOC);
if (!$b || ($jenis==='denda' && !isAdmin() && (int)$b['user_id']!==(int)$_SESSION['user_id'])) { http_response_code(404);exit('Dokumen tidak ditemukan.'); }
if ($jenis==='bast' && $b['status']!=='diserahkan') { http_response_code(404);exit('BAST belum tersedia.'); }
if ($jenis==='bayar' && !empty($b['dibatalkan_at'])) { http_response_code(410);exit('Pembayaran ini sudah dibatalkan.'); }
$file=$jenis==='bast'?$b['foto']:$b['bukti'];
$root=realpath(__DIR__.'/../uploads');$path=$file?realpath($root.'/'.$file):false;
$foto='';if($path && strpos($path,$root.DIRECTORY_SEPARATOR)===0 && is_file($path)) {
    $mime=(new finfo(FILEINFO_MIME_TYPE))->file($path);
    if(in_array($mime,['image/jpeg','image/png','image/webp'],true)) $foto='data:'.$mime.';base64,'.base64_encode(file_get_contents($path));
}
$judulMap=['bast'=>'BERITA ACARA SERAH TERIMA JAMINAN','denda'=>'KWITANSI PEMBAYARAN DENDA','bayar'=>'KWITANSI PEMBAYARAN PINJAMAN','lelang'=>'BUKTI PENJUALAN JAMINAN','bonus'=>'KWITANSI PEMBAYARAN BONUS'];
$judul=$judulMap[$jenis];
$nomor=strtoupper($jenis).'-'.str_pad($id,8,'0',STR_PAD_LEFT);
$tanggalDokumen=$jenis==='bast'?($b['diserahkan_at']??''):($b['created_at']??'');
$tanggalTampil=$tanggalDokumen?formatDateIndonesian(date('Y-m-d',strtotime($tanggalDokumen))):'-';
$koperasi=$db->query('SELECT * FROM koperasi WHERE id=1')->fetch(PDO::FETCH_ASSOC) ?: ['nama'=>APP_NAME,'alamat'=>'-','telepon'=>'-','email'=>'-'];
$teksBast='';if($jenis==='bast'){$template=$db->query('SELECT bast_jaminan FROM layanan_pengaturan WHERE id=1')->fetchColumn();$teksBast=strtr((string)$template,['{nama}'=>$b['nama_lengkap'],'{norek}'=>$b['kode_pinjaman'],'{tanggal}'=>$tanggalTampil]);}
$pernyataanMap=[
    'denda'=>'Telah diterima pembayaran denda pinjaman dari nasabah sebagaimana rincian transaksi di bawah ini.',
    'bayar'=>'Telah diterima pembayaran pinjaman dari nasabah sebagaimana rincian transaksi di bawah ini.',
    'lelang'=>'Dokumen ini mencatat hasil penjualan barang jaminan dan alokasi dana terhadap kewajiban pinjaman nasabah.',
    'bonus'=>'Telah dibayarkan bonus loyalitas kepada anggota berdasarkan perhitungan bunga pinjaman yang diterima koperasi.',
];
$labelBukti=$jenis==='bast'?'Foto bukti penyerahan':($jenis==='lelang'?'Bukti penjualan jaminan':'Bukti pembayaran');
header('Cache-Control: private, no-store');
